export const ImageEvidenceReverseImageSearchStatus = {
  not_implemented: 'not_implemented',
} as const;

/**
 * Metadata captured for an uploaded image. Reverse-image search is not yet implemented.
 */
export interface ImageEvidence {
  id: string;
  sha256: string;
  /** @nullable */
  perceptualHash: string | null;
  /** @nullable */
  width: number | null;
  /** @nullable */
  height: number | null;
  /** @nullable */
  mediaType: string | null;
  byteLength: number;
  /** @nullable */
  originalFilename: string | null;
  extractedText: string;
  evidenceIds: string[];
  reverseImageSearchStatus: ImageEvidenceReverseImageSearchStatus;
}

export type SubmittedOccurrenceEvidenceType = typeof SubmittedOccurrenceEvidenceType[keyof typeof SubmittedOccurrenceEvidenceType];


export const SubmittedOccurrenceEvidenceType = {
  supplied_url: 'supplied_url',
  screenshot: 'screenshot',
  image: 'image',
  source_post: 'source_post',
  quoted_context: 'quoted_context',
  source_metadata: 'source_metadata',
} as const;

export interface SubmittedOccurrenceSourceRelationship {
  fromSourceId: string;
  relationship: ProvenanceRelationshipType;
  status: LineageEdgeStatus;
  confidence: number;
  evidence: LineageEdgeEvidence[];
  reason: string;
}

/**
 * A request-specific occurrence of the submitted claim. Normalized claim text, search results, and wording similarity are not occurrence evidence and cannot populate this object.
 */
export interface SubmittedOccurrence {
  id: string;
  claim: string;
  exactText: string;
  normalizedProposition: string;
  evidenceType: SubmittedOccurrenceEvidenceType;
  /** @nullable */
  sourceUrl: string | null;
  /** @nullable */
  sourceIdentifier: string | null;
  /** @nullable */
  timestamp: string | null;
  /** @nullable */
  sourceContext: string | null;
  evidenceIds: string[];
  /**
     * @minimum 0
     * @maximum 1
     */
  confidence: number;
  evidence: LineageEdgeEvidence[];
  sourceRelationship: SubmittedOccurrenceSourceRelationship | null;
}

/**
 * The outcome of attempting to trace a submitted claim. Deliberately separates what was found, what was not found, and what remains uncertain.
 */
export interface AnalyzeResult {
  extracted_claim: string;
  input_type: InputType;
  trace_status: TraceStatus;
  /** Legacy alias for librarySimilarity. It is not a truth or provenance score. */
  confidence: number;
  matching_strategy: MatchingStrategy;
  lineage: Lineage | null;
  candidates: MatchCandidate[];
  live_search: LiveSearch;
  knownRecordMatch: KnownRecordMatch;
  /** Curated known-case evidence stages, kept separate from the live investigation stages. */
  knownRecordStages: InvestigationStage[];
  knownRecordScores: KnownRecordScores;
  /** True when this response includes a runtime web-evidence investigation rather than only a curated-library lookup. */
  liveInvestigation: boolean;
  evidenceSnapshots: EvidenceSnapshot[];
  sourceVersions: SourceClaimVersion[];
  comparisons: SourceComparison[];
  mutations: DetectedMutation[];
  originAssessment: OriginAssessment;
  dynamicLineage: RuntimeLineageGraph;
  investigationStages: InvestigationStage[];
  /** Similarity between the submitted claim and the closest curated-library record; not a truth score. */
  librarySimilarity: number;
  /** @nullable */
  sourceRelevance: number | null;
  /** @nullable */
  provenanceConfidence: number | null;
  /** @nullable */
  mutationConfidence: number | null;
  /** @nullable */
  originConfidence: number | null;
  /** Evidence-backed completeness of the runtime lineage, from 0 to 1. */
  lineageCompleteness: number;
  imageEvidence: ImageEvidence | null;
  submittedOccurrence: SubmittedOccurrence | null;
  what_we_found: string[];
  what_we_did_not_find: string[];
  uncertainty_notes: string[];
  /** @nullable */
  messenger_safe_explanation: string | null;
  self_check_steps: SelfCheckStep[];
  /**
     * Set when the result was saved to the caller's history
     * @nullable
     */
  analysis_id: string | null;
}

/**
 * Optional request-specific source context for the exact submitted occurrence. Supplying only claim wording is insufficient.
 */
export interface SubmittedOccurrenceInput {
  /**
     * @maxLength 2048
     * @nullable
     */
  sourceUrl?: string | null;
  /**
     * @maxLength 300
     * @nullable
     */
  sourceName?: string | null;
  /**
     * @maxLength 500
     * @nullable
     */
  sourcePostId?: string | null;
  /** @nullable */
  observedAt?: string | null;
  /**
     * @maxLength 5000
     * @nullable
     */
  exactQuote?: string | null;
  /**
     * @maxLength 5000
     * @nullable
     */
  context?: string | null;
}

export interface ClaimTextInput {
  /**
     * @minLength 1
     * @maxLength 5000
     */
  text: string;
  occurrence?: SubmittedOccurrenceInput;
}

export interface ImageAnalysisInput {
  image: Blob;
}

export interface UserProfile {
  userId: string;
  /** @nullable */
  email: string | null;
  /** @nullable */
  displayName: string | null;
  /** @nullable */
  photoURL: string | null;
  createdAt: string;
  lastLoginAt: string;
}

/**
 * Row in the user's history list
 */
export interface AnalysisSummary {
  id: string;
  inputType: InputType;
  extractedClaim: string;
  traceStatus: TraceStatus;
  confidence: number;
  /** @nullable */
  matchedLineageId: string | null;
  createdAt: string;
}

/**
 * A stored analysis belonging to one user
 */
export interface AnalysisRecord {
  id: string;
  userId: string;
  inputType: InputType;
  /** For images this is the OCR-extracted text, never the image bytes */
  originalInput: string;
  result: AnalyzeResult;
  createdAt: string;
}

